+	if err := os.MkdirAll(filepath.Dir(name), 0o700); err != nil { t.Fatal(err) }
+	original := []byte(`{"id":"risk","enabled":true,"prompt":{"template":"old template"}}`)
+	if err := os.WriteFile(name, original, 0o600); err != nil { t.Fatal(err) }
+	runners, err := loadTuneRunners(dir, "")
