+func TestDeepAuditFollowLogRotation(t *testing.T) {
+	t.Parallel()
+	dir := t.TempDir()
+	name := filepath.Join(dir,"entire.log")
+	if err := os.WriteFile(name, []byte("initial\n"), 0o600); err != nil { t.Fatal(err) }
+	root, err := os.OpenRoot(dir)
+	if err != nil { t.Fatal(err) }
+	t.Cleanup(func(){ _ = root.Close() })
+	ctx,cancel := context.WithCancel(t.Context())
+	observer := &deepAuditLogObserver{writes:make(chan string,32)}
+	done := make(chan error,1)
+	go func(){ done <- followFile(ctx,observer,root,"entire.log") }()
+	t.Cleanup(func(){ cancel(); <-done })
+	// Append until a write proves followFile has opened and read this inode.
+	deadline := time.NewTimer(2*time.Second)
+	defer deadline.Stop()
+	ticker := time.NewTicker(40*time.Millisecond)
+	defer ticker.Stop()
+ready:
+	for {
+		select {
+		case <-observer.writes: break ready
+		case <-ticker.C:
+			f,err := os.OpenFile(name,os.O_APPEND|os.O_WRONLY,0o600)
+			if err != nil { t.Fatal(err) }
+			_,err = f.WriteString("before rotation\n"); _ = f.Close()
+			if err != nil { t.Fatal(err) }
+		case <-deadline.C: t.Fatal("followFile never read initial appended marker")
+		}
+	}
+	if err := os.Rename(name,name+".1"); err != nil { t.Fatal(err) }
+	if err := os.WriteFile(name,[]byte("after rotation\n"),0o600); err != nil { t.Fatal(err) }
+	wait := time.NewTimer(time.Second)
+	defer wait.Stop()
+	for {
+		select {
+		case chunk := <-observer.writes:
+			if strings.Contains(chunk,"after rotation") { return }
+		case <-wait.C: t.Error("--follow stayed on the rotated inode and missed the new log file"); return
+		}
+	}
+}
