+			ownKey := cursor.ChatsWorkspaceKey(repo)
+			for i := 1; i < size.workspaces; i++ {
+				if err := os.Mkdir(filepath.Join(chats, fmt.Sprintf("%032x", i)), 0o700); err != nil {
+					b.Fatal(err)
+				}
+			}
+			ids := make([]string, size.sessions)
