+	before := []byte("previous valuable archive")
+	if err := os.WriteFile(out,before,0o600); err != nil { t.Fatal(err) }
+	err := writeDoctorBundle(context.Background(),repo,out,true)
+	if err == nil { t.Fatal("expected refusal of symlinked .entire") }
+	after, readErr := os.ReadFile(out)
+	if readErr != nil { t.Fatal(readErr) }
